// A programmable four-bit pattern detector.
//
// The ports are the contract. The later milestones instantiate this
// module by exactly these names, so changing one breaks them.

module seq_match (
    input  logic       clk,
    input  logic       rst_n,     // synchronous, active low
    input  logic       din,       // one bit per clock
    input  logic [3:0] pattern,   // held steady; pattern[3] arrives first
    output logic       found      // registered: high for one cycle on a match
);

    // your code here.
    //
    // Three pieces of state and no more:
    //
    //   hist  the last four bits that arrived, oldest at the top
    //   fill  how many bits have arrived since reset, so that the
    //         register cannot match on the zeros it was reset to
    //   found the output, which is registered
    //
    // `found` must be high during the cycle AFTER the edge that
    // clocked in the last bit of the pattern, for exactly one cycle.

    assign found = 1'b0;

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench for the detector. Submit uses another one, with
// longer streams, the overlapping cases and a reset in the middle.
module tb;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n   = 1'b1;
  logic din     = 1'b0;
  logic [3:0] pattern = 4'b1011;
  logic found;

  seq_match dut (.clk(clk), .rst_n(rst_n), .din(din),
                 .pattern(pattern), .found(found));

  integer hits;
  integer i;

  // One cycle: drive at the falling edge, return just after the rising
  // one. `found` is a Moore output, so what it reads here is the value
  // produced by the edge that just happened.
  task tick(input logic b);
    begin
      @(negedge clk); din = b;
      @(posedge clk); #1;
      if (found) hits = hits + 1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
      hits = 0;
    end
  endtask

  // The low `n` bits of `bits`, most significant first.
  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) tick(bits[i]);
    end
  endtask

  logic f_after_reset, f_mid, f_after_1011;
  integer one_hit, other_hits;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    f_after_reset = found;

    tick(1'b1); f_mid = found;
    tick(1'b0);
    tick(1'b1);
    tick(1'b1); f_after_1011 = found;

    tick(1'b0);
    tick(1'b0);
    one_hit = hits;

    // The pattern is an input, so the same design finds a different one.
    pattern = 4'b1100;
    reset();
    stream(4, 4'b1100);
    other_hits = hits;

    $display("CHECK quiet_after_reset 0 %0d AT %0d", f_after_reset, $time);
    $display("CHECK no_early_fire 0 %0d AT %0d", f_mid, $time);
    $display("CHECK fires_on_1011 1 %0d AT %0d", f_after_1011, $time);
    $display("CHECK exactly_one_hit 1 %0d AT %0d", one_hit, $time);
    $display("CHECK finds_another_pattern 1 %0d AT %0d", other_hits, $time);
    $display("DONE 5");
    $finish;
  end

endmodule
